import heapq

def stable_toposort(graph):
    # Validate dependencies and compute in-degrees, reverse edges
    in_degree = {}
    reverse = {node: [] for node in graph}
    original_index = {node: i for i, node in enumerate(graph)}

    for node, deps in graph.items():
        # Use a set to handle duplicate dependencies
        deps_set = set(deps)
        for dep in deps_set:
            if dep not in graph:
                raise ValueError(f"Missing dependency: {dep}")
            reverse[dep].append(node)
        in_degree[node] = len(deps_set)

    # Initialize heap with nodes having zero in-degree
    heap = []
    for node in graph:
        if in_degree[node] == 0:
            heapq.heappush(heap, (original_index[node], node))

    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for dependent in reverse[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, (original_index[dependent], dependent))

    if len(result) != len(graph):
        raise ValueError("Cycle detected")

    return result
