        for k, v in d.items():
            full = f"{prefix}.{k}" if prefix else k
            if isinstance(v, dict):
                collect_leaf_paths(v, full, kind)
            else:
                diffs.append(f"{kind}:{full}")

    def compare(e, a, path):
        # Missing keys in expected
        for key in e:
            cur = f"{path}.{key}" if path else key
            if key not in a:
                if isinstance(e[key], dict):
                    collect_leaf_paths(e[key], cur, "missing")
                else:
                    diffs.append(f"missing:{cur}")
            else:
                e_val = e[key]
                a_val = a[key]
                if isinstance(e_val, dict) and isinstance(a_val, dict):
                    compare(e_val, a_val, cur)
                elif isinstance(e_val, dict) != isinstance(a_val, dict):
                    diffs.append(f"type:{cur}")
                else:  # both leaves
                    if e_val != a_val:
                        diffs.append(f"type:{cur}")

        # Extra keys in actual
        for key in a:
            if key not in e:
                cur = f"{path}.{key}" if path else key
                if isinstance(a[key], dict):
                    collect_leaf_paths(a[key], cur, "extra")
                else:
                    diffs.append(f"extra:{cur}")

    compare(expected, actual, "")
    return sorted(diffs)
