def merge_payload_ranges(items):
    # Validate items
    for start, end, payload in items:
        if start > end:
            raise ValueError(f"Invalid range: start {start} > end {end}")

    if not items:
        return []

    # Sort by start, then end
    sorted_items = sorted(items, key=lambda x: (x[0], x[1]))

    merged = []
    cur_start, cur_end, cur_payload = sorted_items[0]

    for start, end, payload in sorted_items[1:]:
        # Check if this range can merge with current: same payload and overlapping/touching
        if payload == cur_payload and start <= cur_end + 1:
            # Extend current end if needed
            if end > cur_end:
                cur_end = end
        else:
            # Flush current
            merged.append([cur_start, cur_end, cur_payload])
            cur_start, cur_end, cur_payload = start, end, payload

    # Append the last one
    merged.append([cur_start, cur_end, cur_payload])

    return merged
